function englishLayer(chapter: KybalionChapter): CorpusLayer {
  return {
    key: "eng-1908",
    layer: "primary_text",
    sourceKey: "kybalion-1908",
    content: chapter.text,
    language: "English",
    licence: "public_domain",
    evidence: `${KYBALION_1908_EVIDENCE} (${chapter.id === "intro" ? "the Introduction" : `chapter ${chapter.numeral}`}, pp. ${chapter.firstPage}–${chapter.lastPage})`,
  };
}

