function sayingsNote(chapter: KybalionChapter): string {
  const count = KYBALION_SAYINGS.filter((s) => s.chapter === chapter.id).length;
  if (count === 0) return "";
  return ` The chapter quotes ${count === 1 ? "one saying" : `${count} sayings`} as from 'The Kybalion'.`;
}

function chapterPassage(chapter: KybalionChapter): CorpusPassage {
  const meta = CHAPTERS[chapter.id];
  const key = `${BOOK}.${chapter.id}`;
  const where = chapter.id === "intro" ? "Introduction" : `chapter ${chapter.numeral}, '${chapter.title}'`;
  return {
    key,
    parentKey: BOOK,
    divisionKind: "chapter",
    label: meta.label,
    reference: `The Kybalion (Chicago, 1908), ${where}, pp. ${chapter.firstPage}–${chapter.lastPage}`,
    sourceKey: "kybalion-1908",
    summary: meta.summary,
    notes: ((meta.notes ?? "") + sayingsNote(chapter)).trim() || undefined,
    verificationStatus: "unverified",
    layers: [englishLayer(chapter)],
    themes: meta.themes.map(([themeKey, note]) => ({ themeKey, note })),
    images: imagesFor(KYBALION_IMAGES, key),
  };
}

function buildPassages(): CorpusPassage[] {
  return [
    {
      key: BOOK,
      divisionKind: "book",
      label: "The Kybalion (Chicago, 1908)",
      reference:
        "The Kybalion: A Study of the Hermetic Philosophy of Ancient Egypt and Greece, by Three Initiates (Chicago: The Yogi Publication Society, Masonic Temple, 1908), 223 pp.: Introduction and chapters I–XV",
      sourceKey: "kybalion-1908",
      summary:
        "A New Thought book of 1908 that presents seven 'Hermetic Principles' (Mentalism, Correspondence, Vibration, Polarity, Rhythm, Cause and Effect, Gender) as the teaching of Hermes Trismegistus, handed down in an unwritten collection of maxims called the Kybalion, and applies them to the mental healing, suggestion and self-mastery of its day.",
      notes:
        "The book's account of its source, an oral Hermetic tradition from the time of Abraham, is its own claim. The Seven Principles are not in the Corpus Hermeticum or the Asclepius, and the sayings it quotes as 'The Kybalion' have no known ancient source. Its 'As above, so below' echoes the second line of the Latin Emerald Tablet, which it calls only 'the old Hermetic axiom'. Its ideas and vocabulary (mental healing, suggestion, vibration, the 'dual mind') are those of the New Thought movement of its day, which it names: 'mental science' and 'new-thought phenomena', it says, work by its principle of mental transmutation (chapter III). It is signed only 'The Three Initiates' and is usually attributed to William Walker Atkinson; see the dates for the evidence.",
      verificationStatus: "unverified",
      layers: CITED,
      dates: DATES,
      images: imagesFor(KYBALION_IMAGES, BOOK),
    },
    ...KYBALION_CHAPTERS.map(chapterPassage),
  ];
}

